<script>function profileEditor(employee){return {data:structuredClone(employee),original:null,editing:false,active:'Personal Information',error:'',tabs:['Personal Information','Employment Details','Compensation','Attendance Summary','Payroll History'],startEdit(){this.original=structuredClone(this.data);this.editing=true},cancel(){this.data=this.original;this.editing=false;this.error=''},save(){for(let f of ['full_name','position','department','employment_type','employment_status'])if(!this.data[f]){this.error=f.replaceAll('_',' ')+' is required.';return}this.editing=false;this.error='';this.$dispatch('show-toast',{message:'Profile saved (demo).'})}}}</script>
